local function norm(v)return tostring(v or""):match("(%d+)")or""end
local function source(m)return m:GetAttribute("SourceAssetName")or m:GetAttribute("TreeType")end
local function tf(root,b)local e=root:FindFirstChild(b.."Environment")local s=e and e:FindFirstChild("Scenery")return s and s:FindFirstChild("Trees")end
local function parts(i)local a={}for _,d in ipairs(i:GetDescendants())do if d:IsA("BasePart")then table.insert(a,d)end end table.sort(a,function(x,y)return x:GetFullName()<y:GetFullName()end)return a end
local function sig(i)local ids={}local prim={}for _,p in ipairs(parts(i))do if p:IsA("MeshPart")then table.insert(ids,norm(p.MeshId))else table.insert(prim,p.ClassName..":"..(p:IsA("Part")and tostring(p.Shape)or"NA"))end end table.sort(ids)table.sort(prim)return"M|"..#ids.."|"..table.concat(ids,",").."|P|"..#prim.."|"..table.concat(prim,",")end
local function hasImage(p)if p:IsA("MeshPart")and p.TextureID~=""then return true end for _,d in ipairs(p:GetChildren())do if d:IsA("SurfaceAppearance")and(d.ColorMap~=""or d.NormalMap~="")then return true end if(d:IsA("Texture")or d:IsA("Decal"))and d.Texture~=""then return true end end return false end
local function clean(i)for _,d in ipairs(i:GetDescendants())do if d:IsA("LuaSourceContainer")or d:IsA("ProximityPrompt")or d:IsA("ClickDetector")then d:Destroy()end end end
local function box(i)return i:GetBoundingBox()end
local function load(x)local got,last for attempt,delay in ipairs({0,1,2,4})do if delay>0 then task.wait(delay)end local ok,v=pcall(function()return IS:LoadAsset(x.assetId)end)if ok then got=v break else last=v warn("AK_V5_RETRY source="..x.source.." attempt="..attempt)end end if not got then error("Load failed "..x.source..": "..tostring(last))end clean(got)got.Parent=nil local pp=parts(got)if #pp==0 then got:Destroy()error("No geometry: "..x.source)end for _,p in ipairs(pp)do if p:IsA("MeshPart")and norm(p.MeshId)==""then got:Destroy()error("Missing MeshId: "..x.source)end end local _,z=box(got)if z.X<=0 or z.Y<=0 or z.Z<=0 then got:Destroy()error("Bad bounds: "..x.source)end print("AK_V5_TEMPLATE source="..x.source.." parts="..#pp.." signature="..sig(got).." bounds="..tostring(z))return got end
local function role(s,p,i,n)local q=p.Name:lower()local sl=s:lower()if n>1 and(q:find("snow")or q:find("ice")or q:find("frost"))then return"SNOW"elseif q:find("rock")or q:find("stone")then return"ROCK"elseif q:find("crystal")or q:find("gem")then return"CRYSTAL"elseif q:find("flower")or q:find("petal")then return"FLOWER"elseif q:find("fruit")or q:find("coconut")then return"FRUIT"elseif q:find("trunk")or q:find("wood")or q:find("bark")or q:find("branch")or q:find("stem")then return"WOOD"elseif q:find("bush")or q:find("leaf")or q:find("foliage")or q:find("canopy")then return"FOLIAGE"elseif sl:find("cactus")then return"CACTUS"elseif s=="Mystic Tree_Rock_Bush"then if p.Material==Enum.Material.Rock or p.Material==Enum.Material.Slate then return"ROCK"end return"FOLIAGE"elseif s:find("Dead")or s:find("_dead")or s:find("Bare")then return"DEAD_WOOD"elseif n>1 and i==1 then return"WOOD"else return"FOLIAGE"end end
local function tint(p,c,wood,r)local target=c local material=Enum.Material.Grass if r=="WOOD"or r=="DEAD_WOOD"then target=wood;material=Enum.Material.Wood elseif r=="SNOW"then target=Color3.fromRGB(235,245,248);material=Enum.Material.Snow elseif r=="ROCK"then target=Color3.fromRGB(76,68,91);material=Enum.Material.Slate elseif r=="CRYSTAL"then material=Enum.Material.Glass elseif r=="FLOWER"then target=c:Lerp(Color3.fromRGB(239,124,198),.45);material=Enum.Material.SmoothPlastic elseif r=="FRUIT"then target=Color3.fromRGB(126,79,43);material=Enum.Material.Wood elseif r=="CACTUS"then material=Enum.Material.Grass end p.Color=hasImage(p)and target:Lerp(Color3.new(1,1,1),.27)or target;if not hasImage(p)then p.Material=material end end
local function fitTree(template,cf,height,baseY,name,s)local n=template:Clone()n.Name=name;n:SetAttribute("SourceAssetName",s);n:SetAttribute("TreeType",s)local _,z=box(n)n:ScaleTo(n:GetScale()*height/z.Y)n:PivotTo(cf)local b,sz=box(n)n:TranslateBy(Vector3.new(cf.Position.X-b.Position.X,baseY-(b.Position.Y-sz.Y/2),cf.Position.Z-b.Position.Z))for _,p in ipairs(parts(n))do p.Anchored=true end return n end
local function deterministicYaw(name)local h=0 for i=1,#name do h=(h*33+string.byte(name,i))%36000 end return math.rad(h/100)end
local function getTreePlacementRecord(model)local bc,sz=box(model)local pp=parts(model)local representative=nil local best=-math.huge for _,p in ipairs(pp)do if p.Transparency<1 then local q=p.Name:lower()local semantic=(q:find("trunk")or q:find("wood")or q:find("bark")or q:find("branch"))and 1000000 or 0 local lower=(bc.Position.Y-p.Position.Y)*100 local volume=p.Size.X*p.Size.Y*p.Size.Z local score=semantic+lower+volume;if score>best then best=score;representative=p end end end local yaw if representative then local _,y,_=representative.CFrame:ToOrientation();yaw=y else local ok,pivot=pcall(function()return model:GetPivot()end)if ok then local _,y,_=pivot:ToOrientation();yaw=y else yaw=deterministicYaw(model.Name)end end local baseY=bc.Position.Y-sz.Y*.5 local position=Vector3.new(bc.Position.X,baseY,bc.Position.Z)return{model=model,name=model.Name,boxCF=bc,boxSize=sz,position=position,base=baseY,height=sz.Y,originalRadius=math.clamp(math.max(sz.X,sz.Z)*.32,2.25,10),yaw=yaw,cf=CFrame.new(position)*CFrame.Angles(0,yaw,0)}end
print("[1/9] Audit 295 current trees")local root=W:FindFirstChild("BiomeEnvironments")if not root then error("BiomeEnvironments missing")end local current={}local total=0 local oldSig={}
for _,b in ipairs(BIOMES)do current[b]={}local f=tf(root,b)if not f then error(b.." Trees missing")end for _,m in ipairs(f:GetChildren())do if not m:IsA("Model")then error("Non-model tree")end local s=source(m)current[b][s]=current[b][s]or{}table.insert(current[b][s],m)total=total+1 local g=sig(m)if oldSig[s]and oldSig[s]~=g then error("Inconsistent source geometry "..s)end oldSig[s]=g end end if total~=295 then error("Expected 295, got "..total)end
print("[2/9] Loading and validating 24 selected assets")local templates={}local finalSig={}for _,b in ipairs(BIOMES)do templates[b]={}for _,s in ipairs(FINAL[b])do if current[b][s]then local t=current[b][s][1]:Clone()clean(t)t.Parent=nil;templates[b][s]=t;finalSig[s]=sig(t)end end end
for _,x in ipairs(SPECS)do local t=load(x)templates[x.biome][x.source]=t;finalSig[x.source]=sig(t)end local owner={}local familyN=0 for _,b in ipairs(BIOMES)do for _,s in ipairs(FINAL[b])do local g=finalSig[s]if not g then error("Missing template "..b.."/"..s)end if owner[g]then error("Geometry collision "..s.." / "..owner[g])end owner[g]=s;familyN=familyN+1 end end if familyN~=96 then error("Final registry not 96")end
print("[3/9] Resolve actual geometry-based tree positions")local recordsByBiome={}local falseZeroPairs=0
for _,b in ipairs(BIOMES)do local records={}for _,list in pairs(current[b])do for _,m in ipairs(list)do table.insert(records,getTreePlacementRecord(m))end end table.sort(records,function(a,z)local p,q=a.position,z.position return(math.floor(p.X/19)*31+math.floor(p.Z/19)*17)<(math.floor(q.X/19)*31+math.floor(q.Z/19)*17)end)local zero=0 local unique={}for _,x in ipairs(records)do unique[string.format("%.1f:%.1f",x.position.X,x.position.Z)]=true end for i=1,#records do for j=i+1,#records do local a,z=records[i],records[j]local d=(Vector3.new(a.position.X,0,a.position.Z)-Vector3.new(z.position.X,0,z.position.Z)).Magnitude;if d<.1 then zero=zero+1;warn("AK_V5_POSITION_COLLISION biome="..b.." treeA="..a.model:GetFullName().." boxA="..tostring(a.boxCF).."/"..tostring(a.boxSize).." treeB="..z.model:GetFullName().." boxB="..tostring(z.boxCF).."/"..tostring(z.boxSize))end end end local un=0 for _ in pairs(unique)do un=un+1 end print("AK_V5_POSITION_SANITY")print("biome="..b)print("trees="..#records)print("uniqueXZPositions="..un)print("zeroDistancePairs="..zero)falseZeroPairs=falseZeroPairs+zero;recordsByBiome[b]=records end
if falseZeroPairs>0 then error("Geometry-position sanity failed before mutation: zero-distance pairs="..falseZeroPairs)end
local SPACING={Meadow=10,Forest=8.5,Jungle=7.5,Desert=13,Snow=9.5,Volcano=10.5,Ocean=9.5,AncientRuins=9.5,MagicalForest=7.5,Sky=11.5,Prehistoric=7.5,Mythical=8.5}
local function classifyZone(p)
 local n=p.Name:lower() local parent=p.Parent and p.Parent.Name:lower()or"" local text=n.." "..parent
 if text:find("label")or text:find("billboard")or text:find("sign")then return"LABEL_MARKER"end
 if text:find("debug")then return"DEBUG_MARKER"end
 if text:find("helper")then return"HELPER"end
 if text:find("shakeable")then if p.Transparency>=.95 and not p.CanCollide then return"CLEARING_GUIDE"else return"SHAKEABLE_GAMEPLAY"end end
 if text:find("clear")then return"CLEARING_GUIDE"end
 if text:find("entrance")or text:find("exit")then return"REAL_ENTRANCE"end
 if text:find("path")then if p.Transparency>=.95 and not p.CanCollide then return"HELPER"else return"REAL_PATH"end end
 if text:find("spawn")or text:find("town")or text:find("plaza")or text:find("sanctuary")or text:find("collection")then return"REAL_ENTRANCE"end
 if text:find("marker")then return"DEBUG_MARKER"end
 return"UNKNOWN"
end
local function zoneRecord(p,category)
 if category=="DEBUG_MARKER"or category=="LABEL_MARKER"or category=="HELPER"or category=="UNKNOWN"then return nil end
 if category=="CLEARING_GUIDE"then return{kind="circle",position=p.Position,radius=math.clamp(math.min(p.Size.X,p.Size.Z)*.25,5,12),source=p}
 elseif category=="SHAKEABLE_GAMEPLAY"then return{kind="circle",position=p.Position,radius=10,source=p}
 else return{kind="rect",part=p,pad=4,source=p}end
end
local function blockedByZone(point,z)
 if z.kind=="circle"then return(Vector3.new(point.X,0,point.Z)-Vector3.new(z.position.X,0,z.position.Z)).Magnitude<z.radius end
 local lp=z.part.CFrame:PointToObjectSpace(point)return math.abs(lp.X)<z.part.Size.X/2+z.pad and math.abs(lp.Z)<z.part.Size.Z/2+z.pad
end
local function footprint(template,height)local _,z=box(template)local scale=height/z.Y return math.clamp(math.max(z.X,z.Z)*scale*.32,2.25,10)end
local function lcg(seed)return function()seed=(seed*48271)%2147483647 return seed/2147483647 end end

local function descendantOfNamed(i,words)local p=i.Parent while p and p~=W do local n=p.Name:lower()for _,w in ipairs(words)do if n:find(w,1,true)then return true end end p=p.Parent end return false end
local FLOOR_EXCLUDE={"trees","rocks","decor","transition","label","presentation","future","marker","helper","debug","crystal"}
local function eligibleGround(p,medianY)
 if not p:IsA("BasePart")or not p.Anchored or p.Transparency>=1 then return false end
 if descendantOfNamed(p,FLOOR_EXCLUDE)then return false end
 local n=p.Name:lower()for _,w in ipairs(FLOOR_EXCLUDE)do if n:find(w,1,true)then return false end end
 local horizontal=math.abs(p.CFrame.UpVector:Dot(Vector3.yAxis))>=.88
 local topY=p.Position.Y+p.Size.Y*.5
 return horizontal and p.Size.X*p.Size.Z>=100 and math.abs(topY-medianY)<=18
end
local function insidePartXZ(p,point,tolerance)local q=p.CFrame:PointToObjectSpace(point)tolerance=tolerance or 0 return math.abs(q.X)<=p.Size.X*.5+tolerance and math.abs(q.Z)<=p.Size.Z*.5+tolerance end
local function groundContains(partsList,point,tolerance)for _,p in ipairs(partsList)do if insidePartXZ(p,point,tolerance)then return true,p end end return false,nil end
local function makeRayParams(env)local omit={}local scenery=env:FindFirstChild("Scenery")if scenery then for _,n in ipairs({"Trees","Rocks","Decor","Plants","Presentation"})do local x=scenery:FindFirstChild(n)if x then table.insert(omit,x)end end end for _,d in ipairs(env:GetDescendants())do if d:IsA("BasePart")and(classifyZone(d)~="UNKNOWN"or descendantOfNamed(d,{"transition","label","helper","debug"}))then table.insert(omit,d)end end local rp=RaycastParams.new()rp.FilterType=Enum.RaycastFilterType.Exclude;rp.FilterDescendantsInstances=omit;rp.IgnoreWater=false return rp end
local function rayGround(point,params)return W:Raycast(Vector3.new(point.X,point.Y+100,point.Z),Vector3.new(0,-200,0),params)end
local function assignmentSlots(b)local q,r=math.floor(TARGET[b]/8),TARGET[b]%8 local a={}for i,s in ipairs(FINAL[b])do for _=1,q+(i<=r and 1 or 0)do table.insert(a,s)end end return a end
local function optimizeAssignments(b,positions,slots)
 local openness={}for i,x in ipairs(positions)do local nearest=math.huge for j,y in ipairs(positions)do if i~=j then local d=(Vector3.new(x.position.X,0,x.position.Z)-Vector3.new(y.position.X,0,y.position.Z)).Magnitude;if d<nearest then nearest=d end end end table.insert(openness,{index=i,value=nearest})end table.sort(openness,function(a,z)return a.value>z.value end)
 local ranked={}for _,s in ipairs(slots)do table.insert(ranked,{source=s,width=footprint(templates[b][s],positions[1].height)})end table.sort(ranked,function(a,z)if a.width==z.width then return a.source<z.source end return a.width>z.width end)
 local out={}for i,x in ipairs(openness)do out[x.index]=ranked[i].source end
 local function penalty(i,j)local a,z=positions[i],positions[j]local dist=(Vector3.new(a.position.X,0,a.position.Z)-Vector3.new(z.position.X,0,z.position.Z)).Magnitude local ra=footprint(templates[b][out[i]],a.height)local rz=footprint(templates[b][out[j]],z.height)local originalPenetration=math.max(0,a.originalRadius+z.originalRadius+1-dist)local newPenetration=math.max(0,ra+rz+1-dist)return math.max(0,newPenetration-originalPenetration-1.5)end
 local function affected(i,j)local v=penalty(i,j)for k=1,#positions do if k~=i and k~=j then v=v+penalty(math.min(i,k),math.max(i,k))+penalty(math.min(j,k),math.max(j,k))end end return v end
 for _=1,8 do local improved=false for i=1,#positions-1 do for j=i+1,#positions do local before=affected(i,j)out[i],out[j]=out[j],out[i]local after=affected(i,j)if after+1e-4<before then improved=true else out[i],out[j]=out[j],out[i]end end end if not improved then break end end
 return out
end

print("[4/9] Resolve biome ground/protected zones")
local biomeData={}local groundFailures={}local supportOutside=0
local function resolveBiomeGround(b)
 local env=root:FindFirstChild(b.."Environment")local f=tf(root,b)if not env or not f then error("Biome environment missing "..b)end
 local positions=recordsByBiome[b]local heights={}local supports={}local treeSupports={}local shakeSupports={}
 for _,x in ipairs(positions)do table.insert(heights,x.height);table.insert(treeSupports,x.position);table.insert(supports,x.position)end
 for _,d in ipairs(env:GetDescendants())do if d:IsA("BasePart")and d.Name:lower():find("futureshakeablespot",1,true)then table.insert(shakeSupports,d.Position);table.insert(supports,d.Position)end end
 table.sort(heights)
 local baseYs={}for _,p in ipairs(treeSupports)do table.insert(baseYs,p.Y)end table.sort(baseYs)local medianY=baseYs[math.ceil(#baseYs/2)]
 local pool={}local seen={}for _,p in ipairs(env:GetDescendants())do if p:IsA("BasePart")then table.insert(pool,p);seen[p]=true end end local biomeKey=b:lower()for _,p in ipairs(W:GetDescendants())do if p:IsA("BasePart")and not seen[p]then local path=p:GetFullName():lower()local n=p.Name:lower()if path:find(biomeKey,1,true)and(n:find("floor",1,true)or n:find("ground",1,true)or n:find("plot",1,true)or path:find("biomeplot",1,true)or path:find("biomefloor",1,true))then table.insert(pool,p);seen[p]=true end end end
 local candidates={}for _,p in ipairs(pool)do if eligibleGround(p,medianY)then
  local ti,si=0,0 for _,x in ipairs(treeSupports)do if insidePartXZ(p,x,2)then ti=ti+1 end end for _,x in ipairs(shakeSupports)do if insidePartXZ(p,x,2)then si=si+1 end end
  local coverage=(ti+si)/math.max(1,#supports)local yfit=1-math.min(1,math.abs((p.Position.Y+p.Size.Y*.5)-medianY)/18)local score=coverage*100+yfit*8+math.min(5,(p.Size.X*p.Size.Z)/2000)
  table.insert(candidates,{part=p,coverage=coverage,score=score,tree=ti,shake=si})
  print("AK_V5_FLOOR_CANDIDATE")print("biome="..b)print("path="..p:GetFullName())print("size="..tostring(p.Size))print("position="..tostring(p.Position))print("topY="..(p.Position.Y+p.Size.Y*.5))print("area="..(p.Size.X*p.Size.Z))print("horizontal=true")print("treeSupportPointsInside="..ti)print("shakeableSupportPointsInside="..si)print("totalSupportCoverage="..coverage)print("score="..score)
 end end
 table.sort(candidates,function(a,z)return a.score>z.score end)local grounds={}local covered={}
 for _,c in ipairs(candidates)do local adds=false for i,p in ipairs(supports)do if not covered[i]and insidePartXZ(c.part,p,2)then adds=true break end end if adds then table.insert(grounds,c.part)for i,p in ipairs(supports)do if insidePartXZ(c.part,p,2)then covered[i]=true end end end local n=0 for _ in pairs(covered)do n=n+1 end if n/math.max(1,#supports)>=.95 then break end end
 local params=makeRayParams(env)local rayAccepted=0 for i,p in ipairs(supports)do local hit=rayGround(p,params)local accepted=false if hit then local valid=false for _,c in ipairs(candidates)do if c.part==hit.Instance then valid=true break end end if valid then accepted=true;rayAccepted=rayAccepted+1 local exists=false for _,g in ipairs(grounds)do if g==hit.Instance then exists=true end end if not exists then table.insert(grounds,hit.Instance)end covered[i]=true end end print("AK_V5_GROUND_RAYCAST")print("biome="..b)print("supportPoint="..tostring(p))print("hitPath="..(hit and hit.Instance:GetFullName()or"NONE"))print("hitPosition="..(hit and tostring(hit.Position)or"NONE"))print("hitNormal="..(hit and tostring(hit.Normal)or"NONE"))print("accepted="..tostring(accepted))end
 local inside=0 local minX,maxX,minZ,maxZ=math.huge,-math.huge,math.huge,-math.huge local area=0 local topYs={}
 for _,g in ipairs(grounds)do area=area+g.Size.X*g.Size.Z;local c=g.Position;minX=math.min(minX,c.X-g.Size.X*.5);maxX=math.max(maxX,c.X+g.Size.X*.5);minZ=math.min(minZ,c.Z-g.Size.Z*.5);maxZ=math.max(maxZ,c.Z+g.Size.Z*.5);table.insert(topYs,g.Position.Y+g.Size.Y*.5)end
 for _,p in ipairs(supports)do if groundContains(grounds,p,3)then inside=inside+1 end end table.sort(topYs)local coverage=inside/math.max(1,#supports)local supportMissing=#supports-inside local treeOutside=0 for _,p in ipairs(treeSupports)do if not groundContains(grounds,p,3)then treeOutside=treeOutside+1 end end
 print("AK_V5_GROUND_RESOLVED")print("biome="..b)print("groundParts="..#grounds)print("combinedUsableArea="..area)print("supportCoverage="..coverage)print("minX="..minX)print("maxX="..maxX)print("minZ="..minZ)print("maxZ="..maxZ)print("medianTopY="..(topYs[math.ceil(#topYs/2)]or 0))
 if #grounds==0 or supportMissing>0 or rayAccepted/math.max(1,#supports)<.8 or treeOutside>0 then table.insert(groundFailures,b.." grounds="..#grounds.." coverage="..coverage.." rayCoverage="..(rayAccepted/math.max(1,#supports)).." supportsOutside="..supportMissing.." treesOutside="..treeOutside)end supportOutside=supportOutside+supportMissing
 local slots=assignmentSlots(b)
 return{env=env,folder=f,positions=positions,heights=heights,median=heights[math.ceil(#heights/2)],grounds=grounds,area=area,rayParams=params,allSlots=slots}
end
for _,b in ipairs(BIOMES)do biomeData[b]=resolveBiomeGround(b)end
if #groundFailures>0 then error("Ground resolver stopped before mutation: "..table.concat(groundFailures,","))end

print("AK_V5_PROTECTED_ZONE_AUDIT_BEGIN")
local globalZoneParts={}for _,d in ipairs(W:GetDescendants())do if d:IsA("BasePart")then local c=classifyZone(d)local n=d.Name:lower()if c=="REAL_ENTRANCE"and(n:find("spawn")or n:find("town")or n:find("plaza")or n:find("sanctuary")or n:find("collection"))then table.insert(globalZoneParts,d)end end end
for _,b in ipairs(BIOMES)do local d=biomeData[b]local zones={}local ignored=0 for _,p in ipairs(d.env:GetDescendants())do if p:IsA("BasePart")then local c=classifyZone(p)if c~="UNKNOWN"then local z=zoneRecord(p,c)if z then table.insert(zones,z)else ignored=ignored+1 end print("AK_V5_PROTECTED_AUDIT")print("biome="..b)print("path="..p:GetFullName())print("name="..p.Name)print("size="..tostring(p.Size))print("position="..tostring(p.Position))print("transparency="..p.Transparency)print("CanCollide="..tostring(p.CanCollide))print("CanQuery="..tostring(p.CanQuery))print("category="..c)end end end for _,p in ipairs(globalZoneParts)do table.insert(zones,zoneRecord(p,"REAL_ENTRANCE"))end d.zones=zones;d.ignored=ignored end

print("[5/9] Optimize size-aware assignments")for _,b in ipairs(BIOMES)do local d=biomeData[b]local existingSlots={}for i=1,#d.positions do existingSlots[i]=d.allSlots[i]end d.assignments=optimizeAssignments(b,d.positions,existingSlots)end
local finalPlan={}local originalOverlap={}local overlapViolations=0 local worsenedLegacy=0 local newOverlapViolations=0
for _,b in ipairs(BIOMES)do local d=biomeData[b]finalPlan[b]={}for i,x in ipairs(d.positions)do local s=d.assignments[i]local r=footprint(templates[b][s],x.height)table.insert(finalPlan[b],{biome=b,source=s,position=x.position,cf=x.cf,height=x.height,base=x.base,radius=r,originalRadius=x.originalRadius,existing=true,name=x.name})end
 for i=1,#d.positions do for j=i+1,#d.positions do local a,z=d.positions[i],d.positions[j]local dist=(Vector3.new(a.position.X,0,a.position.Z)-Vector3.new(z.position.X,0,z.position.Z)).Magnitude;originalOverlap[i..":"..j..":"..b]=math.max(0,a.originalRadius+z.originalRadius+1-dist)end end
 for i=1,#finalPlan[b]do for j=i+1,#finalPlan[b]do local a,z=finalPlan[b][i],finalPlan[b][j]local dist=(Vector3.new(a.position.X,0,a.position.Z)-Vector3.new(z.position.X,0,z.position.Z)).Magnitude local required=a.radius+z.radius+1 local originalPenetration=originalOverlap[i..":"..j..":"..b]or 0 local newPenetration=math.max(0,required-dist)local bad=newPenetration-originalPenetration>1.5 if bad then print("AK_V5_OVERLAP_VIOLATION")print("biome="..b)print("treeA="..a.name)print("treeB="..z.name)print("distance="..dist)print("requiredDistance="..required)print("treeAPosition="..tostring(a.position))print("treeBPosition="..tostring(z.position))print("treeARadius="..a.radius)print("treeBRadius="..z.radius)print("existingOrNew=EXISTING_ASSIGNMENT")overlapViolations=overlapViolations+1;worsenedLegacy=worsenedLegacy+1 end end end
end
if overlapViolations>0 then error("Size-aware assignment could not eliminate preserved-position footprint violations: "..overlapViolations)end

print("[6/9] Preflight all 75 additions and all final footprints")
local planned={}local placementFailures={}local totalPlanned=0
for _,b in ipairs(BIOMES)do local d=biomeData[b]local need=TARGET[b]-#d.positions planned[b]={}local occupied={}for _,x in ipairs(finalPlan[b])do table.insert(occupied,x)end local attempts=0 local usedSpacing=SPACING[b]local random=lcg(104729+#b*1009)local stages={{factor=1,margin=12,tries=2000},{factor=.9,margin=10,tries=2000},{factor=.8,margin=8,tries=2000},{factor=.7,margin=6,tries=2000}}
 for _,stage in ipairs(stages)do usedSpacing=SPACING[b]*stage.factor for _=1,stage.tries do if #planned[b]>=need then break end attempts=attempts+1 local slotIndex=#d.positions+#planned[b]+1 local s=d.allSlots[slotIndex]local h=d.median*(.82+math.floor(random()*5)*.08)local radius=footprint(templates[b][s],h)local totalArea=0 for _,g in ipairs(d.grounds)do totalArea=totalArea+g.Size.X*g.Size.Z end local pick=random()*totalArea local g=d.grounds[#d.grounds]for _,x in ipairs(d.grounds)do pick=pick-x.Size.X*x.Size.Z;if pick<=0 then g=x break end end local inset=math.max(stage.margin,radius*.75)local lx=(random()-.5)*math.max(1,g.Size.X-2*inset)local lz=(random()-.5)*math.max(1,g.Size.Z-2*inset)local seedPoint=g.CFrame:PointToWorldSpace(Vector3.new(lx,g.Size.Y*.5+1,lz))local hit=rayGround(seedPoint,d.rayParams)local accepted=hit and groundContains(d.grounds,hit.Position,1)or false
  if accepted then local point=hit.Position local safe=true for _,z in ipairs(d.zones)do if blockedByZone(point,z)then safe=false break end end if safe then for _,o in ipairs(occupied)do local dist=(Vector3.new(point.X,0,point.Z)-Vector3.new(o.position.X,0,o.position.Z)).Magnitude local required=math.max(radius+o.radius+(SPACING[b]<=8.5 and .5 or 1),usedSpacing)if dist<required then safe=false break end end end if safe then local item={biome=b,source=s,position=point,cf=CFrame.new(point)*CFrame.Angles(0,random()*math.pi*2,0),height=h,base=point.Y,radius=radius,existing=false,name=s.."_NEW_"..(#planned[b]+1)}table.insert(planned[b],item);table.insert(occupied,item);table.insert(finalPlan[b],item)end end
 end if #planned[b]>=need then break end end
 local newBad=0 for i=1,#finalPlan[b]do for j=i+1,#finalPlan[b]do local a,z=finalPlan[b][i],finalPlan[b][j]if not(a.existing and z.existing)then local dist=(Vector3.new(a.position.X,0,a.position.Z)-Vector3.new(z.position.X,0,z.position.Z)).Magnitude local required=a.radius+z.radius+(SPACING[b]<=8.5 and .5 or 1)local bad=dist<required if bad then print("AK_V5_OVERLAP_VIOLATION")print("biome="..b)print("treeA="..a.name)print("treeB="..z.name)print("distance="..dist)print("requiredDistance="..required)print("treeAPosition="..tostring(a.position))print("treeBPosition="..tostring(z.position))print("treeARadius="..a.radius)print("treeBRadius="..z.radius)print("existingOrNew="..(a.existing and"EXISTING_NEW"or z.existing and"NEW_EXISTING"or"NEW_NEW"))newBad=newBad+1 end end end end newOverlapViolations=newOverlapViolations+newBad;overlapViolations=overlapViolations+newBad;totalPlanned=totalPlanned+#planned[b]
 print("AK_V5_PLACEMENT_PREFLIGHT")print("biome="..b)print("existingTrees="..#d.positions)print("requiredAdditions="..need)print("usableFloorArea="..d.area)print("realProtectedZones="..#d.zones)print("ignoredHelperMarkers="..d.ignored)print("candidatePositionsFound="..#planned[b])print("minimumSpacingUsed="..usedSpacing)print("attemptsUsed="..attempts)
 if #planned[b]~=need then table.insert(placementFailures,b.." found="..#planned[b].." required="..need)end
end
if totalPlanned~=75 or overlapViolations>0 or #placementFailures>0 then error("Full placement preflight stopped before mutation: additions="..totalPlanned.." overlaps="..overlapViolations.." failures="..table.concat(placementFailures,","))end

local rb=Instance.new("Folder")rb.Name=RB;rb.Parent=SS local made={}local moved={}
local function rollback(e)for _,m in ipairs(made)do if m.Parent then m:Destroy()end end for i=#moved,1,-1 do moved[i].m.Parent=moved[i].p end rb:Destroy()for _,x in pairs(templates)do for _,t in pairs(x)do t:Destroy()end end W:SetAttribute(MARK,nil)error("V5 rollback: "..tostring(e))end
print("[7/9] Rebuild + add")local added=0 local ok,err=pcall(function()for _,b in ipairs(BIOMES)do local d=biomeData[b]for _,list in pairs(current[b])do for _,m in ipairs(list)do m.Parent=rb;table.insert(moved,{m=m,p=d.folder})end end for i,x in ipairs(finalPlan[b])do local n=fitTree(templates[b][x.source],x.cf,x.height,x.base,x.source.."_V5_"..string.format("%03d",i),x.source)n.Parent=d.folder;table.insert(made,n)if not x.existing then added=added+1 end end end end)if not ok then rollback(err)end if added~=75 then rollback("Expected 75 additions, got "..added)end
print("[8/9] Recolor + live validate")local okC,errC=pcall(function()for _,b in ipairs(BIOMES)do local idx={}for i,s in ipairs(FINAL[b])do idx[s]=i end for _,m in ipairs(tf(root,b):GetChildren())do local s=source(m)local pp=parts(m)for i,p in ipairs(pp)do tint(p,PAL[b][idx[s]],WOOD[b],role(s,p,i,#pp))end end end end)if not okC then rollback(errC)end
local count=0 local sources={}local geometry={}local white=0 local protectedViolations=0 local outside=0
for _,b in ipairs(BIOMES)do local d=biomeData[b]local localS={}for _,m in ipairs(tf(root,b):GetChildren())do count=count+1 local s=source(m)localS[s]=true;if sources[s]and sources[s]~=b then rollback("Cross-biome source reuse "..s)end sources[s]=b local g=sig(m)if geometry[g]and geometry[g]~=s then rollback("Final geometry collision "..s.." / "..geometry[g])end geometry[g]=s local bc,sz=box(m)local base=Vector3.new(bc.Position.X,bc.Position.Y-sz.Y*.5,bc.Position.Z)if not groundContains(d.grounds,base,3)then outside=outside+1 end local pp=parts(m)for i,p in ipairs(pp)do local r=role(s,p,i,#pp)if p.Color.R>.97 and p.Color.G>.97 and p.Color.B>.97 and r~="SNOW"and r~="FLOWER"then white=white+1;warn("AK_UNEXPECTED_WHITE "..p:GetFullName())end end end for _,x in ipairs(planned[b])do for _,z in ipairs(d.zones)do if blockedByZone(x.position,z)then protectedViolations=protectedViolations+1 end end end local n=0 for _ in pairs(localS)do n=n+1 end if n~=8 or #tf(root,b):GetChildren()~=TARGET[b]then rollback(b.." final count/family validation failed")end end local sn=0 for _ in pairs(sources)do sn=sn+1 end if count~=370 or sn~=96 or white~=0 or protectedViolations>0 or outside>0 then rollback("Final validation failed trees="..count.." families="..sn.." white="..white.." protected="..protectedViolations.." outside="..outside)end
print("[9/9] Final report")for _,x in pairs(templates)do for _,t in pairs(x)do t:Destroy()end end W:SetAttribute(MARK,true)print("ANIMAL KINGDOM TRUE TREE VARIETY V5 COMPLETE")print("Trees: "..count)print("Families: "..sn)print("Added trees: "..added)for _,b in ipairs(BIOMES)do print(b..": "..#tf(root,b):GetChildren().." / 8")end print("False zero-distance pairs: "..falseZeroPairs)print("New overlap violations: "..newOverlapViolations)print("Worsened legacy overlaps: "..worsenedLegacy)print("Protected-zone violations: "..protectedViolations)print("Ground failures: 0")print("Support points outside resolved biome ground: "..supportOutside)print("Outside biome ground: "..outside)print("Unexpected pure-white non-snow parts: "..white)print("Geometry collisions: 0")print("Cross-biome reuse: 0")print("Rollback: ServerStorage."..RB)print("Texture/content ID writes: 0")print("MeshId writes: 0")print("Script Source writes: 0")print("Failures: 0")
